mapper.update:
UPDATE NOTIFICATION
SET NOTI_MESSAGE = #{notiMessage},
    CREATED_AT   = SYSTIMESTAMP
WHERE USER_NO           = #{userNo}
  AND NOTI_URL          = #{notiUrl}
  AND NOTIFICATION_TYPE = #{notificationType}
  AND IS_READ           = 'N'

mapper.select:
SELECT COUNT(*) FROM NOTIFICATION 
WHERE USER_NO = #{userNo} 
AND IS_READ = 'N'
